// normalizeStageType maps friendly stage_type words to the numeric enum the
// Productive API requires (1=Deal, 2=Budget). Numeric input passes through.
func normalizeStageType(v string) string {
	switch strings.ToLower(strings.TrimSpace(v)) {
	case "deal", "deals":
		return "1"
	case "budget", "budgets":
		return "2"
	default:
		return v
	}
}

